async () => {
const {plansApi,requestId}=await import('/src/plansApi.js'); const {request}=await import('/src/api.js');
let p=await plansApi.create(requestId()); window.__checkoutPlan=p;
const challenge=await plansApi.prepare(p,'rename','Flight checkout verification'); p=await plansApi.commit({plan:p,operation:'rename',title:'Flight checkout verification',challenge:challenge.challenge,id:requestId()}); window.__checkoutPlan=p;
const fields={finalDestination:'Milan',dateStart:'2026-11-26',dateEnd:'2026-11-29',travelers:2,flights:'needed',accommodation:'not-needed'};
const changes=[{operation:'add_candidate',field:'candidates',value:'Milan',source:'user_edit'},...Object.entries(fields).map(([field,value])=>({operation:'set',field,value,source:'user_edit'}))];
const context=await request('/v1/plans/'+p.plan_id+'/research-context',{changes},{method:'PATCH',headers:{'Idempotency-Key':requestId(),'If-Match':'1'}});
const card={status:'ready',need:'needed',bookingStatus:'not-booked',title:'Flights to Milan',subtitle:'2 travelers',detail:'2026-11-26 → 2026-11-29',availability:'unavailable'};
const components={essentials:{status:'ready',dates:{start:'2026-11-26',end:'2026-11-29',note:'',flexible:false},travelers:2,budget:{label:'',noFixedBudget:false}},map:{status:'ready',destination:'Milan',final:true,pins:[]},flights:card,accommodation:{...card,need:'not-needed',title:'Stay in Milan'}};
p=await plansApi.get(p.plan_id); const saved=await plansApi.saveCanvas(p,{context_revision:context.revision,snapshot:{version:1,components,evidence:{}}},requestId());
const {writeCanvasView}=await import('/src/features/plans/canvasViewState.js');writeCanvasView(p.plan_id,{canvas:true,chatOpen:false});
window.__checkoutPlan=await plansApi.get(p.plan_id); return {planId:p.plan_id,savedRevision:saved.revision};
}

